// React
import React from "react"
import { BrowserRouter, Navigate, Route, Routes } from "react-router-dom"

// Third Party
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { AaReactProvider, AuthBase, ErrorPage } from "aa-geuthur-react";
import { NuqsAdapter } from "nuqs/adapters/react-router/v8";

// AA bpforge
import { AppName, ProjectName } from "@/constants";
import AdministrationPage from "@/Pages/AdministrationPage";
import MainPage from "@/Pages/MainPage";
import MyBlueprintsPage from "@/Pages/MyBlueprintsPage";
import OrdersPage from "@/Pages/OrdersPage";
import SettingsPage from "@/Pages/SettingsPage";

const queryClient = new QueryClient();

function Routing() {
  return (
    <React.StrictMode>
      <AaReactProvider projectName={ProjectName} appName={AppName} menuRefetchInterval={30000}>
        <QueryClientProvider client={queryClient}>
          <BrowserRouter>
            <NuqsAdapter>
              <Routes>
                <Route path={`/${ProjectName}/`} element={<AuthBase />}>
                  <Route index element={<MainPage />} />
                  <Route path="overview/" element={<Navigate to={`/${ProjectName}/`} replace />} />
                  <Route path="my-blueprints/" element={<MyBlueprintsPage />} />
                  <Route path="orders/" element={<OrdersPage />} />
                  <Route path="settings/" element={<SettingsPage />} />
                  <Route path="administration/" element={<AdministrationPage />} />
                  <Route path="*" element={<ErrorPage />} />
                </Route>
                <Route path="*" element={<Navigate to={`/${ProjectName}/`} replace />} />
              </Routes>
            </NuqsAdapter>
          </BrowserRouter>
        </QueryClientProvider>
      </AaReactProvider>
    </React.StrictMode>
  )
}

export default Routing